+#if defined(__APPLE__)
+/* No prctl on macOS. The handlers below already treat a prctl failure as
+ * "unsupported" and let FEX fall back, so a shim that fails is enough for
+ * everything except PR_SET_VMA, which is a cosmetic mapping name that nothing
+ * on macOS would ever read -- report success for that and fail the rest. See
+ * Engine/fex-macos-fixups.py for why each one cannot be implemented. */
+#include <errno.h>
+#ifndef PR_SET_VMA
+#define PR_SET_VMA 0x53564d41
+#endif
+static inline int prctl(int op, ...) {
+  if (op == PR_SET_VMA) return 0;
+  errno = ENOSYS;
+  return -1;
+}
+#else
 #include <sys/prctl.h>
+#endif
 #include <unistd.h>

 #include "FEXUnixLib.h"
